 for i in items:
  n=i['number'];uid=i['id'];block+=f'<article class="fl-correction"><label for="fl-answer-{uid}"><b>{n}.</b> <span data-glossary>{escape(i["prompt"])}</span></label><textarea id="fl-answer-{uid}" rows="2" spellcheck="false" aria-describedby="fl-feedback-{uid}" placeholder="Write the requested word or amount."></textarea><div class="fl-feedback" id="fl-feedback-{uid}" hidden></div><button type="button" class="btn btn-secondary" data-fl-model="{uid}" hidden>Listen to one model {n}</button></article>'
